import XCTest
@testable import ConduitMenuBarCore

/// Allow-once eligibility against real `git diff` output.
///
/// Each fixture is the exact text of a patch generated with git 2.54 in a
/// throwaway repo (or a minimal hand edit of one), and its effect was
/// checked with `git apply --numstat --summary` and a real `git apply` on
/// the base files X, Y, R.txt, img.bin and src/app.ts. file.patch runs
/// plain `git apply` (-p1) in the project root, so a notification may offer
/// Allow once only when that effect is one in-place edit of the one file it
/// names. Generated by gen_swift_fixtures.py (desk packet); regenerate rather
/// than hand-editing the escaped strings.
final class AllowOnceGitFixtureTests: XCTestCase {
    /// Patches that do more than edit the one file in place.
    static let mustDecline: [(name: String, effect: String, patch: String)] = [
        ("extraNewFile", "edits X and creates N.txt", "diff --git a/N.txt b/N.txt\nnew file mode 100644\nindex 0000000..53c74cd\n--- /dev/null\n+++ b/N.txt\n@@ -0,0 +1 @@\n+evil\ndiff --git a/X b/X\nindex ce01362..14be0d4 100644\n--- a/X\n+++ b/X\n@@ -1 +1 @@\n-hello\n+hello2\n"),
        ("modeOnly", "mode change 100644 => 100755 Y", "diff --git a/Y b/Y\nold mode 100644\nnew mode 100755\n"),
        ("editPlusModeOnly", "edits X; mode change 100644 => 100755 Y", "diff --git a/X b/X\nindex ce01362..14be0d4 100644\n--- a/X\n+++ b/X\n@@ -1 +1 @@\n-hello\n+hello2\ndiff --git a/Y b/Y\nold mode 100644\nnew mode 100755\n"),
        ("emptyNewFile", "create mode 100644 Z (empty)", "diff --git a/Z b/Z\nnew file mode 100644\nindex 0000000..e69de29\n"),
        ("editPlusEmptyNewFile", "edits X; creates empty Z", "diff --git a/X b/X\nindex ce01362..14be0d4 100644\n--- a/X\n+++ b/X\n@@ -1 +1 @@\n-hello\n+hello2\ndiff --git a/Z b/Z\nnew file mode 100644\nindex 0000000..e69de29\n"),
        ("headerNamesDiffer", "header says Y; git edits src/app.ts (the ---/+++ names)", "diff --git a/Y b/Y\nindex cc798ff..66d48fc 100644\n--- a/src/app.ts\n+++ b/src/app.ts\n@@ -1 +1 @@\n-export const a = 1;\n+export const a = 2;\n"),
        ("headerNewNameDiffers", "header says a/src/app.ts b/Y; git edits src/app.ts", "diff --git a/src/app.ts b/Y\nindex cc798ff..66d48fc 100644\n--- a/src/app.ts\n+++ b/src/app.ts\n@@ -1 +1 @@\n-export const a = 1;\n+export const a = 2;\n"),
        ("rename", "rename R.txt => R2.txt (100%)", "diff --git a/R.txt b/R2.txt\nsimilarity index 100%\nrename from R.txt\nrename to R2.txt\n"),
        ("renameWithEdit", "delete R.txt; create R2.txt", "diff --git a/R.txt b/R.txt\ndeleted file mode 100644\nindex 3367afd..0000000\n--- a/R.txt\n+++ /dev/null\n@@ -1 +0,0 @@\n-old\ndiff --git a/R2.txt b/R2.txt\nnew file mode 100644\nindex 0000000..233035a\n--- /dev/null\n+++ b/R2.txt\n@@ -0,0 +1,2 @@\n+old\n+more\n"),
        ("delete", "delete mode 100644 Y", "diff --git a/Y b/Y\ndeleted file mode 100644\nindex 975fbec..0000000\n--- a/Y\n+++ /dev/null\n@@ -1 +0,0 @@\n-y\n"),
        ("newSymlink", "create mode 120000 link", "diff --git a/link b/link\nnew file mode 120000\nindex 0000000..555dec9\n--- /dev/null\n+++ b/link\n@@ -0,0 +1 @@\n+/etc/hosts\n\\ No newline at end of file\n"),
        ("editPlusSymlink", "edits X; create mode 120000 link", "diff --git a/X b/X\nindex ce01362..14be0d4 100644\n--- a/X\n+++ b/X\n@@ -1 +1 @@\n-hello\n+hello2\ndiff --git a/link b/link\nnew file mode 120000\nindex 0000000..555dec9\n--- /dev/null\n+++ b/link\n@@ -0,0 +1 @@\n+/etc/hosts\n\\ No newline at end of file\n"),
        ("binaryEdit", "binary change to img.bin", "diff --git a/img.bin b/img.bin\nindex c7527cebe464374893c8ea2a74ff17b9f46f5eea..159ec97f4ea9760665e0e17479758606892a7f1e 100644\nGIT binary patch\nliteral 7\nOcmZQzO3KVL;sO8#Spj$e\n\nliteral 6\nNcmZQzOv=pT0ssTF0Yv}+\n\n"),
        ("editPlusHiddenBinaryExecutable", "edits X; create mode 100755 run.sh (binary)", "diff --git a/X b/X\nindex ce01362..14be0d4 100644\n--- a/X\n+++ b/X\n@@ -1 +1 @@\n-hello\n+hello2\ndiff --git a/run.sh b/run.sh\nnew file mode 100755\nindex 0000000000000000000000000000000000000000..775912fe074c707cf399df76e94259ecc86f3d98\nGIT binary patch\nliteral 22\ndcmY#Z)KALH(=X28N=?qlS12gYOHJWo002xD2B-i4\n\nliteral 0\nHcmV?d00001\n\n"),
        ("multiFile", "edits X and Y", "diff --git a/X b/X\nindex ce01362..14be0d4 100644\n--- a/X\n+++ b/X\n@@ -1 +1 @@\n-hello\n+hello2\ndiff --git a/Y b/Y\nindex 975fbec..1a78173 100644\n--- a/Y\n+++ b/Y\n@@ -1 +1 @@\n-y\n+y2\n"),
        ("crlfHiddenTraditionalNewFile", "edits X; creates Q (git trims the CR from the name)", "diff --git a/X b/X\nindex ce01362..14be0d4 100644\n--- a/X\n+++ b/X\n@@ -1 +1 @@\n-hello\n+hello2\r\n--- /dev/null\r\n+++ b/Q\r\n@@ -0,0 +1 @@\r\n+evil\r\n"),
        ("crlfHiddenGitNewFile", "edits X; create mode 100644 Q", "diff --git a/X b/X\nindex ce01362..14be0d4 100644\n--- a/X\n+++ b/X\n@@ -1 +1 @@\n-hello\n+hello2\r\ndiff --git a/Q b/Q\r\nnew file mode 100644\r\n--- /dev/null\r\n+++ b/Q\r\n@@ -0,0 +1 @@\r\n+evil\r\n"),
        ("combiningMarkHiddenEdit", "edits X and Y (-p1 strips the U+0301 a/ component)", "diff --git a/X b/X\nindex ce01362..14be0d4 100644\n--- a/X\n+++ b/X\n@@ -1 +1 @@\n-hello\n+hello2\n--- \u{301}a/Y\n+++ \u{301}b/Y\n@@ -1 +1 @@\n-y\n+evil\n"),
        ("combiningMarkHiddenModeChange", "edits X; mode change 100644 => 100755 Y", "diff --git a/X b/X\nindex ce01362..14be0d4 100644\n--- a/X\n+++ b/X\n@@ -1 +1 @@\n-hello\n+hello2\ndiff --git \u{301}a/Y \u{301}b/Y\nold mode 100644\nnew mode 100755\n"),
        ("combiningMarkHiddenNewFile", "edits X; creates Q", "diff --git a/X b/X\nindex ce01362..14be0d4 100644\n--- a/X\n+++ b/X\n@@ -1 +1 @@\n-hello\n+hello2\n--- /dev/null\n+++ \u{301}b/Q\n@@ -0,0 +1 @@\n+evil\n"),
    ]

    /// edits src/app.ts only
    static let singleInPlaceEdit = "diff --git a/src/app.ts b/src/app.ts\nindex cc798ff..66d48fc 100644\n--- a/src/app.ts\n+++ b/src/app.ts\n@@ -1 +1 @@\n-export const a = 1;\n+export const a = 2;\n"

    func testOnlyASingleInPlaceEditIsOfferedAllowOnce() {
        let ask = Fixtures.approval(tool: "file.patch", path: nil, patch: Self.singleInPlaceEdit)
        XCTAssertEqual(AllowOnce.eligibility(for: ask), .eligible(path: "src/app.ts"))
        XCTAssertEqual(AskNotification.make(for: ask).categoryIdentifier, AskNotification.categoryAllowOnce)
    }

    func testGitPatchesThatDoMoreThanOneInPlaceEditAreNeverOfferedAllowOnce() {
        for fixture in Self.mustDecline {
            let ask = Fixtures.approval(tool: "file.patch", path: nil, patch: fixture.patch)
            let message = "\(fixture.name): git apply \(fixture.effect)"
            XCTAssertEqual(AllowOnce.eligibility(for: ask), .ineligible, message)
            let note = AskNotification.make(for: ask)
            XCTAssertEqual(note.categoryIdentifier, AskNotification.categoryReviewOnly, message)
            XCTAssertNil(note.userInfo["path"], message)
        }
    }
}
